  console.log("#" + id, "[" + r.invoice.number, "$" + r.invoice.amount, "recv", r.received_at + "]", "->", l.category, l.rank, "=>", l.v0_category);
  console.log("  BODY:", JSON.stringify(r.body));
  console.log("  NOTE:", l.note);
}
const combos = {};
