    expect(r("1/5")).toBe("2027-01-05");
    expect(r("January 1")).toBe("2027-01-01");
    expect(r("Nov 20")).toBe("2026-11-20");
    expect(r("November 20th")).toBe("2026-11-20");
    expect(r("20 November")).toBe("2026-11-20");
